import{_ as e,o as t,c as i,a6 as n}from"./chunks/framework.De615z8S.js";const h=JSON.parse('{"title":"维护手册","description":"","frontmatter":{},"headers":[],"relativePath":"maintenance.md","filePath":"maintenance.md"}'),o={name:"maintenance.md"};function r(l,a,c,d,s,p){return t(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="维护手册" tabindex="-1">维护手册 <a class="header-anchor" href="#维护手册" aria-label="Permalink to &quot;维护手册&quot;">​</a></h1><h2 id="内容改在哪里" tabindex="-1">内容改在哪里 <a class="header-anchor" href="#内容改在哪里" aria-label="Permalink to &quot;内容改在哪里&quot;">​</a></h2><p>正文与完整模板在docs/；仓库、工具、平台与发现来源在data/。资源ID由正文resource_ids引用。资源卡、导航、网站与下载件自动生成。目录描述完整建设范围，正文与实操状态分别记录。</p><h2 id="一次维护" tabindex="-1">一次维护 <a class="header-anchor" href="#一次维护" aria-label="Permalink to &quot;一次维护&quot;">​</a></h2><ol><li>运行<code>npm run maintain -- --discover --limit 3</code>，轮转读取任务检索词及重点仓库。</li><li>阅读<code>.maintenance/latest.json</code>中的新增、变化、失败、待续页和影响页面。对高价值候选运行<code>npm run maintain -- --repo owner/repo</code>取得README与文件树。</li><li>阅读实际来源。候选的用途、输入、输出、许可和依赖明确后，独立编写资料卡；只改来源支持的事实。版本提交活跃不等于教程已失效。</li><li>用resource_ids定位受影响正文，修订具体步骤或限制，更新CHANGELOG.md及maintenance/reviews/。</li><li>运行相关测试及<code>npm run build</code>，查看受影响页面、完整模板和必要导出。常规修订用普通Git提交发布；未确认变化只留待核。</li></ol><h2 id="失败与日期" tabindex="-1">失败与日期 <a class="header-anchor" href="#失败与日期" aria-label="Permalink to &quot;失败与日期&quot;">​</a></h2><p>每个来源失败独立记录，其他来源继续；失败查询保留成功页位置，下轮到该查询时重试。多页搜索记录next_page和未完范围，最多检索GitHub搜索允许的范围，不宣称全量。</p><p>检索词或入口类型改变时，从新条件的第一页读取并保留旧条件记录，避免复用旧页位置漏掉新结果。候选的review_status与新发现时间分开，再次发现不覆盖已收录、待核或本轮不收录的复核状态。</p><p>运行时间记录在本地报告；来源核对日记录在经过内容复核的资料卡；正文修改日记录在正文。无有效变化不刷新公开日期。首次读取标first_observations，避免当成仓库刚发生变化。</p><p>公开运行无需凭证但可能限流；可使用环境变量GITHUB_TOKEN或本机已配置的Git凭证，凭证只在内存中发给api.github.com，不进输出、日志或仓库。不会执行外部README／Skill命令。</p><h2 id="周期与边界" tabindex="-1">周期与边界 <a class="header-anchor" href="#周期与边界" aria-label="Permalink to &quot;周期与边界&quot;">​</a></h2><p>每周一集中维护，月内第一次周维护增加平台、依赖与来源健康复核。同一入口已手动试跑；具体调度状态见本机运行记录。电脑与Codex应用运行时才能访问本地文件。</p><p>月度入口加<code>--monthly</code>，记录公开工具／平台／来源入口的HTTP与重定向状态。请求失败只列待核，不能据此宣称来源失效；成功也不能代替规则正文的核对。</p><p>独立提示词库与既有来源采集器维持原维护流程。本仓库复用链接和只读来源记录，原件仍留原资料池。内部候选、采集原响应和本机配置不公开。</p><p>待补真实案例见maintenance/backlog.md。平台实际粘贴、PS操作、图像与视频生成需要另外执行，源文件与构建成功不能代替这些结果。</p>',15)])])}const _=e(o,[["render",r]]);export{h as __pageData,_ as default};
